import React from 'react';
import '../styles/searchPage.css';

function Comic({ characters }) {
  // Array of URLs that indicate an image is not available
  const notAvailableImages = [
    "http://i.annihil.us/u/prod/marvel/i/mg/b/40/image_not_available.jpg",
    "https://i.annihil.us/u/prod/marvel/i/mg/f/60/4c002e0305708.gif"
  ];

  return (
    <div className="comic-book-content">
      {characters.map((character) => {
        // Construct the full image URL for the current character
        const characterImageUrl = `${character.thumbnail.path}.${character.thumbnail.extension}`;

        // Check if the character's image URL is in the list of "not available" images
        if (notAvailableImages.includes(characterImageUrl)) {
          // If it is, skip rendering this character by returning null
          return null;
        }

        // Render the character if the image URL is not in the "not available" images
        return (
          <div key={character.id}>
            <h2>{character.name}</h2>
            <img src={characterImageUrl} alt={character.name} />
          </div>
        );
      })}
    </div>
  );
}

export default Comic;
